function filterLearned(){
    const f=formObject(),race=entry(f.race_id),klass=entry(f.class_id),background=entry(f.background_id);
    const schoolNames=[f.school_id,f.secondary_school_id,...checks('additional_school_ids')].map(id=>entry(id)?.name).filter(Boolean);
    const craftNames=checks('craft_ids').map(id=>entry(id)?.name);
    const priorityNames=[f.priority0,f.priority1].map(id=>entry(id)?.name).filter(Boolean);
    const names=[race?.name,klass?.name,background?.name,...craftNames].filter(Boolean);
    const query=el('learned-search')?.value.toLowerCase()||'',all=el('learned-all')?.checked;
    let count=0;
    dialogBody.querySelectorAll('#learned-list>label').forEach(row=>{
        const e=entry(row.dataset.id),selected=row.querySelector('input').checked;
        const relevant=e.data.system||names.includes(e.data.source_name)||schoolNames.includes(e.data.school_name)||priorityNames.includes(e.data.source_group);
        row.dataset.relevant=relevant?'1':'0';
        row.hidden=!(all||relevant||selected)||!row.dataset.name.includes(query);if(!row.hidden)count++;
    });
    el('learned-count').textContent=`· ${count} в списке`;
}
function updateCharacterChoices(reason,initial={}){
    const field=name=>dialogBody.querySelector(`[name="${name}"]`);
    const race=entry(field('race_id').value),klass=entry(field('class_id').value),background=entry(field('background_id').value);
    const sub=field('subrace'),main=field('school_id'),secondary=field('secondary_school_id');
    const values=reason==='initial'?initial:{subrace:sub.value,school_id:main.value,secondary_school_id:secondary.value,additional_school_ids:checks('additional_school_ids')};
    const subs=(race?.data.subraces||[]).map(name=>({id:name,name}));
    const schools=(klass?.data.allowed_schools||[]).map(name=>S.catalog.find(e=>e.kind==='school'&&e.name===name)).filter(Boolean);
    const fill=(select,choices,value,placeholder)=>{
        const valid=choices.some(x=>String(x.id)===String(value)),legacy=reason==='initial'&&value&&!valid;
        select.innerHTML=options(legacy?[...choices,{id:value,name:(entry(value)?.name||value)+' · ранее сохранено'}]:choices,valid||legacy?value:null,placeholder);
        select.disabled=!choices.length&&!legacy;return !!value&&!valid;
    };
    const changed=fill(sub,subs,values.subrace,race?'Выберите подрасу':'Сначала выберите расу')|fill(main,schools,values.school_id,klass?'Выберите основную школу':'Сначала выберите класс')|fill(secondary,schools.filter(e=>String(e.id)!==main.value),values.secondary_school_id,klass?'Выберите дополнительную школу':'Сначала выберите класс');
    el('extra-schools').innerHTML=klass?.data.extra_schools===3?'<p class="notice">Магический универсал: кроме основной доступны три дополнительные школы. Укажите ещё две ниже.</p>'+checkList('additional_school_ids',schools.filter(e=>![main.value,secondary.value].includes(String(e.id))),values.additional_school_ids||[]):'';
    el('choice-hint').textContent=changed?(reason==='initial'?'В листе есть ранее сохранённый выбор вне списка книги. Проверьте подрасу и школы.':'Недоступный вариант сброшен. Выберите новый из списка.'):(klass?`Школы класса: ${(klass.data.allowed_schools||[]).join(', ')}.`:race?'Выберите класс, чтобы открыть список школ.':'Сначала выберите расу и класс.');
    el('elf-choice').hidden=!race?.data.element_damage;
    const trait=race?.data.subrace_traits?.[sub.value];
    el('origin-hint').textContent=[race?.data.chosen_stat_bonus?`Человек: +${race.data.chosen_stat_bonus} к любой характеристике, дополнительно к подрасе (введите в итоговое значение).`:'',trait?.stat?`Подраса: +1 к ${labels[trait.stat]} (введите в итоговое значение).`:'',race?.data.hp_bonus?`Раса: ХП +${race.data.hp_bonus}, учтено автоматически.`:'',race?.data.ac_bonus?`Раса: КД +${race.data.ac_bonus}, учтено автоматически.`:'',klass?.data.proficiencies?'Владения: '+klass.data.proficiencies+'.':'',background?.data.specialization?'Специализация предыстории: '+background.data.specialization+'.':'',klass?.data.starting_equipment?'Начальное снаряжение: '+klass.data.starting_equipment:'',background?.data.starting_equipment?'От предыстории: '+background.data.starting_equipment:''].filter(Boolean).join(' ');
    if(reason==='class_id'||reason==='background_id'){
        const skill=reason==='class_id'?klass?.data.skill:background?.data.skill;
        dialogBody.querySelectorAll('[name="trained"]').forEach(x=>{if(x.value===skill)x.checked=true});
    }
    filterLearned();
}
