function cacheNotes(){if(draftUser)try{localStorage.setItem('vs-notes:'+draftUser,JSON.stringify({drafts,bases:noteBases}))}catch{}}
const noteSaving=new Set();
function syncFocusedNote(){
    const area=el('note-editor');if(!area)return;
    const key=area.dataset.key;if(key in drafts||noteSaving.has(key))return;
    const [kind,id]=key.split(':');
    const text=kind==='shared'?byId(S.campaigns,id)?.notes:byId(S.characters,id)?.private_notes;
    if(typeof text==='string'&&text!==area.value){const start=area.selectionStart,end=area.selectionEnd;area.value=text;area.setSelectionRange(Math.min(start,text.length),Math.min(end,text.length));noteBases[key]=text;}
}
async function noteConflict(){
    const area=el('note-editor');if(!area)return;
    const key=area.dataset.key,[kind,id]=key.split(':'),local=area.value;
    const response=await fetch('/api/state/');const state=await response.json();
    const remote=kind==='shared'?byId(state.campaigns,id).notes:byId(state.characters,id).private_notes;
    modal('Объединить заметки',`<h3>Версия на сервере</h3><div class="entry-desc">${esc(remote)}</div>${textArea('merged','Итоговый текст',local)}`,async()=>{const text=formObject().merged;const r=await api({op:kind==='shared'?'notes.shared':'notes.private',id:num(id),campaign:num(id),text,base:remote});noteBases[key]=r.text;delete drafts[key];cacheNotes();},'Сохранить объединённый текст');
}
async function saveNote(){const area=el('note-editor');if(!area)return;const key=area.dataset.key;if(noteSaving.has(key)){clearTimeout(noteTimer);noteTimer=setTimeout(saveNote,800);return}const [kind,id]=key.split(':'),text=area.value;noteSaving.add(key);try{const response=await api({op:kind==='private'?'notes.private':'notes.shared',id:num(id),campaign:num(id),text,base:noteBases[key]||''});noteBases[key]=response.text;const now=el('note-editor');if(now?.dataset.key===key){if(now.value===text){now.value=response.text;delete drafts[key]}if(el('note-status'))el('note-status').textContent='Сохранено';}else if(drafts[key]===text)delete drafts[key];}catch(e){if(el('note-editor')?.dataset.key===key&&el('note-status')){el('note-status').innerHTML=esc(e.message)+' '+btn('Сравнить и объединить','note.conflict');el('note-status').style.color='var(--red)'}drafts[key]=area.value;}finally{noteSaving.delete(key);cacheNotes()}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}if(e.target.closest('[data-close]')){dialog.close();return}const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const action=b.dataset.do,id=num(b.dataset.id),c=current();try{
if(action==='campaign.tab'){campaignTab=b.dataset.tab;journalFilter='active';journalSearch='';render();return}
if(action==='journal.new'){journalForm(null,b.dataset.kind);return}
if(action==='journal.edit'){journalForm(byId(byId(S.campaigns,campaignId).journal,id));return}
if(action==='journal.step'){el('quest-steps').insertAdjacentHTML('beforeend',questStep());return}
if(action==='journal.step.remove'){b.closest('.quest-step').remove();return}
if(action==='journal.archive'){const r=byId(byId(S.campaigns,campaignId).journal,id);await command({op:'journal.save',campaign:campaignId,id,revision:r.revision,archived:!r.archived});dialog.close();return}
if(action==='effect.remove'){await command({op:'effect.apply',character:num(b.dataset.character),remove:true,effect_key:b.dataset.key});dialog.close();return}
if(action==='effect')effectForm(byId(S.characters,id));else if(action==='check'){const x=byId(S.characters,id);modal('Проверка · '+x.name,selector('skill','Навык',Object.keys(skillStats).map(name=>({id:name,name})),null)+input('roll','Результат физического броска','','number','required')+input('specialization','Применимая специализация (+3, если указана)',''),async()=>{const r=await api({op:'check.roll',character:x.id,...formObject()});return `Результат: ${r.total} (бонус ${r.bonus>=0?'+':''}${r.bonus})`},'Записать результат');return}
if(action==='learned.recommend'){const f=formObject(),names=[entry(f.race_id)?.name,entry(f.class_id)?.name,entry(f.background_id)?.name];dialogBody.querySelectorAll('#learned-list>label').forEach(row=>{const e=entry(row.dataset.id),level=num(f.level),min=e.data.circle===3?8:e.data.circle===2?4:1;if(names.includes(e.data.source_name)&&level>=min)row.querySelector('input').checked=true});filterLearned();return}
if(action==='char.new')characterForm();else if(action==='char.edit')characterForm(byId(S.characters,id));else if(action==='char.open')selectChar(id);else if(action==='tab'){tab=b.dataset.tab;localStorage.setItem('vs-tab',tab);render()}else if(action==='membership')membershipForm(byId(S.characters,id));
else if(action==='crit'){crit=!crit;render()}else if(action==='ability'||action==='aura')abilityForm(c.abilities.find(a=>a.id===id),action==='aura');
else if(action==='support.minor'){const a=c.abilities.find(x=>x.id===id);abilityForm({...a,support_minor:true,data:{...a.data,action:'minor'}})}
else if(action==='reflex')abilityForm({...c.abilities.find(a=>a.id===id),as_reaction:true});
else if(action==='turn'){const scene=byId(S.scenes,c.scene_id);await command({op:'scene.turn',scene:scene.id,version:scene.state})}
else if(action==='undo'||action==='redo'){await command({op:action});toast(action==='undo'?'Ваше действие отменено':'Ваше действие повторено')}
else if(action==='allies'){const scene=byId(S.scenes,c.scene_id);modal('Союзники',scene.state.order.map(id=>{const ally=byId(S.characters,id);return `<div class="list-row">${identity(ally)}<span>${ally.runtime.hp}/${ally.calc.max_hp} ХП</span></div>`}).join(''),null)}
else if(action==='log')modal('Журнал боя',`<div class="log">${S.events.filter(e=>e.scene_id===c.scene_id).map(e=>`<p>${esc(e.label)} ${e.undone?'· отменено':''}<br><small>${esc(e.actor)} · ${new Date(e.time).toLocaleTimeString('ru')}</small>${e.inputs?.roll_result?'<br>Бросок: '+esc(e.inputs.roll_result):''}${e.inputs?.external_effects?.length?'<br>Цель на игровом поле: '+e.inputs.external_effects.map(x=>esc((x.name||labels[x.stat]||x.stat)+' '+x.value+' · '+(x.duration==='battle'?'до конца боя':x.duration==='current_turn'?'до конца текущего хода':x.duration==='actions'?'до пропуска действий':targetTurns(x.turns||3)))).join('; '):''}${instantReactionLog(e.inputs?.instant_reactions)}${periodicDamageLog(e.inputs?.periodic_damage)}${stanceLog(e.inputs)}${weavingLog(e.inputs?.weaving)}${skippedConditionLog(e.inputs?.skipped_conditions)}${attackTargetLog(e.inputs?.attack_targets)}${rollPoolLog(e.inputs?.roll_pool)}${mysticArrowLog(e.inputs?.mystic_arrows)}${transferLog(e.inputs?.exhaustion_transfer)}${chargedLog(e.inputs?.charged_arrows)}${e.inputs?.stun_skipped?`<br>Оглушение: пропущено действий — ${e.inputs.stun_skipped}.`:""}${e.inputs?.total!==undefined?'<br>Итог: '+e.inputs.total:''}</p>`).join('')||'Событий пока нет'}</div>`,null);
else if(action==='stance.water'){waterForm(c)}
else if(action==='weapon.reload'){await api({op:'weapon.reload',character:c.id,item:c.calc.weapon_id})}
else if(action==='action'){if(b.dataset.action==='reaction'){toast('Реакции расходуются при применении умений-реакций');return}modal(actionNames[b.dataset.action],`<label>Операция<select name="exchange"><option value="">Потратить действие</option>${b.dataset.action==='move'&&(c.runtime.effects||[]).some(e=>(e.status||e.name)==='Сбит с ног')?'<option value="stand">Подняться на ноги</option>':''}${b.dataset.action==='main'?'<option value="minor">Обменять на малое</option><option value="move">Обменять на движение</option>':''}</select></label>`,async()=>api({op:'action.spend',character:c.id,action:b.dataset.action,exchange:formObject().exchange}))}
else if(action==='photo')modal('Фотография',`<label>JPEG, PNG или WebP · до 5 МБ<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label>`,async()=>{const r=await fetch('/api/photo/'+id+'/',{method:'POST',headers:{'X-CSRFToken':csrf()},body:new FormData(el('dialog-form'))});if(!r.ok)throw Error(await r.text())});
else if(action==='campaign.new')modal('Новая кампания',input('name','Название','','text','required')+textArea('description','Описание'),async()=>{const r=await api({op:'campaign.create',...formObject()});campaignId=r.id});
else if(action==='squad.new')modal('Новый отряд',input('name','Название','','text','required'),async()=>api({op:'squad.create',campaign:campaignId,...formObject()}));
else if(action==='campaign.join'){await api({op:'campaign.join',campaign:campaignId});await refresh(true)}
else if(action==='campaign.character')characterForm(null,campaignId);
else if(action==='campaign.add'){const mine=S.characters.filter(x=>x.owner_id===S.user.id||S.user.master);if(!mine.length){characterForm(null,campaignId);return}modal('Персонаж для кампании',selector('character','Персонаж',mine,c?.editable?c.id:mine[0]?.id),async()=>{await api({op:'membership',character:num(formObject().character),campaign:campaignId})},'Вступить')}
else if(action==='session.new'){const camp=byId(S.campaigns,campaignId);modal('Новая игровая сессия',input('name','Название','Игровая встреча','','required')+selector('squad','Отряд',camp.squads,camp.squads[0]?.id)+`<h3 class="form-section">Персонажи отряда</h3><div class="checklist" id="session-chars"></div>`,async()=>api({op:'session.create',...formObject(),characters:checks('characters')}),'Создать сессию');updateSessionChars()}
else if(action==='scene.start')initiativeForm(byId(S.sessions,id));
else if(action==='scene.end'){const scene=byId(S.scenes,id);modal('Закончить бой?','<p>ХП участников восстановятся до максимума. Временные ХП и боевые эффекты будут сняты, применения умений восстановятся.</p>',async()=>api({op:'scene.end',scene:id,version:scene.state}),'Закончить бой')}
else if(action==='hp'){const x=byId(S.characters,id);modal('ХП · '+x.name,hp(x)+`<div class="fields"><label>Операция<select name="mode"><option value="damage">Нанести урон</option><option value="heal">Восстановить ХП</option><option value="set">Установить текущие ХП</option><option value="temp">Начислить временные ХП</option><option value="temp_set">Установить остаток временных ХП</option></select></label>${input('value','Количество',0,'number','min="0" required')}</div>`,async()=>api({op:'hp',character:id,...formObject()}),'Применить')}
else if(action==='item.new')itemForm(null,num(b.dataset.character)||null,num(b.dataset.campaign)||null);
else if(action==='item.edit'){const charId=num(b.dataset.character)||null,campId=num(b.dataset.campaign)||null,x=byId(charId?byId(S.characters,charId).items:byId(S.campaigns,campId).items,id);itemForm(x,charId,campId)}
else if(action==='item.transfer')transferItemForm(stockItem(id));
else if(action==='item.equip')await command({op:'item.equip',id,revision:stockItem(id)?.revision});
else if(action==='item.delete'){if(confirm('Удалить этот экземпляр предмета?')){await command({op:'item.delete',id,revision:stockItem(id)?.revision});dialog.close()}}
else if(action==='entry.new')entryForm();else if(action==='entry.edit')entryForm(entry(id));else if(action==='entry.archive'){if(confirm('Архивировать запись?')){await command({op:'entry.save',id,archive:true});dialog.close()}}
else if(action==='catalog.prev'){catalogPage--;render()}else if(action==='catalog.next'){catalogPage++;render()}else if(action==='note.conflict')await noteConflict();else if(action==='note.save')await saveNote();else if(action==='screen'){page='screen';render()}else if(action==='master'){document.body.classList.remove('fullscreen');navigate('master')}else if(action==='fullscreen'){document.body.classList.toggle('fullscreen');if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()}
}catch(err){toast(err.message)}});
function updateSessionChars(){const squad=num(dialogBody.querySelector('[name=squad]')?.value);el('session-chars').innerHTML=S.characters.filter(c=>c.memberships.some(m=>m.squad_id===squad)).map(c=>`<label><input type="checkbox" name="characters" value="${c.id}" checked>${esc(c.name)} · ${esc(c.owner)}</label>`).join('')||'<p>В отряде пока нет персонажей</p>'}
document.addEventListener('change',e=>{const t=e.target;if(t.name.startsWith('reaction:')){updateReactionChoices();return}if(t.name==='reaction'&&el('manual-reactions')){updateManualReactionDetails();return}if(t.id==='journal-filter'){journalFilter=t.value||'all';render();return}if(t.name==='targets'){if(t.checked&&t.dataset.exclusive==='true')dialogBody.querySelectorAll('[name="targets"]').forEach(x=>{if(x!==t)x.checked=false});updateReactionChoices();return}if(t.name==='name'&&el('manual-reactions')){if(['Сон','Страх'].includes(t.value)){const turns=dialogBody.querySelector('[name=turns]');if(turns)turns.value=1}const c=byId(S.characters,el('manual-reactions').dataset.character);el('manual-reactions').innerHTML=selector('reaction','Стихийная реакция',reactionOptions(c,{name:t.value,value:formObject().value}),null)+'<div id="manual-reaction-details"></div>';updateManualReactionDetails();return}if((t.id==='learned-all'||['additional_school_ids','craft_ids','priority0','priority1','abilities'].includes(t.name))&&el('learned-list')){filterLearned();return}if(['race_id','subrace','class_id','school_id','secondary_school_id','background_id'].includes(t.name)&&el('choice-hint')){updateCharacterChoices(t.name);return}if(t.id==='grip-picker'){command({op:'weapon.grip',character:current().id,item:current().calc.weapon_id,grip:t.value}).catch(e=>{toast(e.message);render()});return}if(t.id==='weapon-picker'){command({op:'weapon.select',character:current().id,item:num(t.value)}).catch(e=>toast(e.message));return}if(t.id==='character-picker')selectChar(t.value);else if(t.id==='campaign-picker'){campaignId=num(t.value);render()}else if(t.id==='catalog-kind'){catalogKind=t.value;catalogGroup='';catalogSource='';catalogPage=0;render()}else if(t.id==='catalog-group'){catalogGroup=t.value;catalogSource='';catalogPage=0;render()}else if(t.id==='catalog-source'){catalogSource=t.value;catalogPage=0;render()}else if(t.name==='campaign'&&el('membership-squad'))updateSquads();else if(t.name==='squad'&&el('session-chars'))updateSessionChars();else if(t.id==='item-template'){const e=entry(t.value);if(e){for(const key of ['name','armor','dice','crit','stat','keywords','item_type']){const field=dialogBody.querySelector(`[name="${key}"]`);if(field)field.value=key==='name'?e.name:key==='keywords'?(e.data.keywords||[]).join(', '):e.data[key]||''}}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='journal-search'){journalSearch=t.value;const pos=t.selectionStart;render();el('journal-search').focus();el('journal-search').setSelectionRange(pos,pos);return}if(t.id==='learned-search'){filterLearned();return}if(t.id==='specialization-search'){dialogBody.querySelectorAll('#specialization-list label').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(t.value.toLowerCase()));return}if(t.id==='note-editor'){drafts[t.dataset.key]=t.value;cacheNotes();el('note-status').textContent='Сохранение…';clearTimeout(noteTimer);noteTimer=setTimeout(saveNote,1000);return}if(['catalog-search','character-search','ability-search'].includes(t.id)){const id=t.id,pos=t.selectionStart;if(id==='ability-search')abilitySearch=t.value;else{search=t.value;catalogPage=0}render();const replacement=el(id);replacement.focus();replacement.setSelectionRange(pos,pos)}});
el('dialog-form').addEventListener('submit',async e=>{e.preventDefault();if(busy||!modalSave)return;busy=true;el('dialog-submit').disabled=true;try{const message=await modalSave();dialog.close();if(message?.next){message.next();return}await refresh(true);toast(typeof message==='string'?message:'Сохранено')}catch(err){el('dialog-error').textContent=err.message}finally{busy=false;el('dialog-submit').disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Alt'&&!crit&&!dialog.open){crit=true;render()}});document.addEventListener('keyup',e=>{if(e.key==='Alt'&&crit){crit=false;render()}});window.addEventListener('blur',()=>{if(crit){crit=false;render()}});
window.addEventListener('beforeunload',e=>{if(Object.keys(drafts).length){e.preventDefault();e.returnValue=''}});
document.addEventListener('DOMContentLoaded',()=>{refresh(true);setInterval(()=>refresh(),2000)});

function instantReactionFields(choices,selected,key,f){
 const choice=choices.find(c=>String(c.id)===String(selected));
 if(!choice)return '';
 if(choice.reaction==='Проклятый разряд')return input(key,'Итог броска '+choice.strength+'к6 · без сопротивлений',f[key]||'','number','min="'+choice.strength+'" max="'+choice.strength*6+'" step="1"');
 if(choice.reaction==='Взрыв')return '<p class="notice">Вокруг 2 · '+choice.strength+' физического урона. ХП вносит мастер.</p>';
 if(choice.reaction==='Ледяная тьма')return '<p class="notice">'+choice.strength+' урона цели; '+choice.strength*2+' временных ХП источнику. ХП вносит мастер.</p>';
 return '';
}
function updateManualReactionDetails(){const box=el('manual-reaction-details');if(!box)return;const f=formObject(),c=byId(S.characters,el('manual-reactions').dataset.character);box.innerHTML=instantReactionFields(reactionOptions(c,{name:f.name,value:Number(f.value)}),f.reaction,'reaction_roll',f)}
document.addEventListener('input',e=>{if(e.target.name==='value'&&el('manual-reactions'))updateManualReactionDetails()});
function instantReactionLog(rows){return (rows||[]).map(r=>'<br>'+esc(r.name+' · '+r.target+': '+r.damage+' урона'+(r.damage_type?' ('+r.damage_type+')':'')+(r.area?' · Вокруг '+r.area:'')+(r.ignore_resistance?' · без сопротивлений · бросок '+r.strength+'к6 = '+r.roll:'')+(r.temp_hp?' · '+r.temp_hp+' временных ХП → '+(r.source||'источник'):'')+' · ХП вносит мастер')).join('')}
